package com.healthcare.portal.controller;
import com.healthcare.portal.entity.*; import com.healthcare.portal.repository.*; import com.healthcare.portal.service.EmailService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.security.SecureRandom; import java.time.LocalDateTime; import java.util.Map; import com.healthcare.portal.security.CustomUserDetails;
@RestController @RequestMapping("/api/security") @Tag(name="Security",description="Two-factor authentication and account security") public class SecurityEnterpriseController { private final UserRepository users; private final TwoFactorChallengeRepository repo; private final EmailService email; private final SecureRandom random=new SecureRandom(); public SecurityEnterpriseController(UserRepository u,TwoFactorChallengeRepository r,EmailService e){users=u;repo=r;email=e;}
 @PostMapping("/2fa/send") @Operation(summary="Send a one-time second-factor code by email") public ResponseEntity<?> send(@AuthenticationPrincipal CustomUserDetails ud){User u=users.findById(ud.getId()).orElseThrow();String code=String.format("%06d",random.nextInt(1000000));repo.save(new TwoFactorChallenge(u,code,LocalDateTime.now().plusMinutes(5)));email.send(u.getEmail(),"Healthcare Portal security code","Your verification code is "+code+". It expires in 5 minutes.");return ResponseEntity.ok(Map.of("message","2FA code sent"));}
 @PostMapping("/2fa/verify") public ResponseEntity<?> verify(@AuthenticationPrincipal CustomUserDetails ud,@RequestParam String code){User u=users.findById(ud.getId()).orElseThrow();TwoFactorChallenge c=repo.findAll().stream().filter(x->x.getUser().getId().equals(u.getId())&&!x.isUsed()&&x.getExpiresAt().isAfter(LocalDateTime.now())).reduce((a,b)->b).orElseThrow();if(!c.getCode().equals(code)) return ResponseEntity.badRequest().body(Map.of("message","Invalid code"));c.setUsed(true);repo.save(c);return ResponseEntity.ok(Map.of("verified",true));}
}
